# AUTO-MIGRIERT auf Code-Schluessel (migrate_keys.py).
# Keys: (pfad_oder_basename, "Feld#c:CODE") bzw. "Feld#r:ZEILE" (Quellzeile ohne Code).

DE_SOTO_EM_1 = {
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_0'): 'Du! Wie bist du hierhergekommen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_1'): 'Hä? Was meinst du damit?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_10'): 'Ja. Ich kümmere mich noch immer darum.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_11'): 'Ihr kennt euch also? Das hättest du sagen sollen!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_12'): 'Ich erinnere mich, dass du wieder einmal voreilig\nvorausgeeilt bist, ohne auf mich zu hören.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_13'): 'Wir können später ausführlich reden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_14'): 'Richtig. Wenn wir die anderen nicht holen,\nfinden sie diesen Ort nie.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_15'): 'Ich bin erfreut, dass du das erkannt hast.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_16'): 'Manchmal frage ich mich,\nob du mich aufziehst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_2'): 'Dieser Bergpass ist mit einem Zauber belegt,\nder Eindringlinge in die Irre führt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_3'): 'Nur die, die bereits vom Pass wissen,\nerreichen diesen Ort.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_4'): 'Und derjenige, der mit diesem Wissen bewaffnet ist...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_5'): '...ist niemand anderes als ich.\nEs ist eine Weile her, Ashigumo.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_6'): 'Was für eine Überraschung. Wenn da nicht Takeribis Schwertgeiste wäre!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_7'): 'Wir haben uns vorhin versehentlich mit dir gemeßelt,\nhaber aber keinen Streit mit dir. Gib dich zufrieden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_8'): 'Das ist mein Herr: die Tochter von Lord Takeribi,\nPrinzessin Sakuna.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000201_9'): 'Unter unglücklichen Umständen sind wir gezwungen,\nauf dieser Insel Wohnsitz zu nehmen.\nSteht das Haus noch?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_0'): 'Es ist leicht beschädigt, aber in überraschend\ngutem Zustand. Das ist festes Holz.\nDas Haus ist noch bewohnbar.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_1'): 'Du heißt Ashigumo, richtig? Warum solltest du das Haus\nmeiner Mutter schützen, während all diese Dämonen hier wühlen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_10'): 'Hey! Woher nimmst du es dir, durch mein Haus zu stolpern,\nbevor ich überhaupt einen Fuß hineingesetzt habe?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_11'): 'Du hast lange und hart gearbeitet. Das kann ich sehen.\nWürdest du uns dieses Haus erlauben?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_12'): 'An deiner Seite steht niemand Geringeres als\ndie Tochter Takeribis. Ich kann nicht ablehnen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_13'): 'Das muss Schicksal sein. Lass uns einander helfen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_2'): 'Ich bin deinem Vater zu großem Dank verpflichtet.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_3'): 'Der böse Gott Omizuchi, den deine Eltern hier\nbekämpften, bedrohte auch die Ashigumo-Stammes.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_4'): 'Dein Vater, Lord Takeribi, gab ihnen Kraft\nund Weisheit, und gemeinsam besiegten sie Omizuchi.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_5'): 'Huh. Deshalb also!\nWahrlich eine große Ehre, würde ich sagen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_6'): 'Oh! Hier wohnen? Geht das?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_7'): 'Whoaaaa!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_8'): 'Es ist wiirgendwie huuuuge!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000202_9'): 'Kinta, sieh!\nDahinten sind zwei Zimmer!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_0'): 'Nun haben wir ein Haus, wir sind eingerichtet.\nIhr könnt ab jetzt machen, was ihr wollt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_1'): 'Ich werde mich erholen, bis ich bereit bin,\ndie feierliche Pflicht zu erfüllen,\ndie Lady Kamuhitsuki mir auferlegt hat.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_10'): 'Wenn kein königliches Nickerchen, könnte ich dann wenigstens\nköniglich bis morgen prokrastinieren?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_11'): 'Göttin, sollen wir in diesem Feld etwas pflanzen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_12'): 'Das ist eine großartige Idee, aber zuerst\nmüssen wir Samen finden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_13'): 'Ich habe hier gerade Reisspelzen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_14'): 'Mein Wort! Wie unglaublich bequem.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_15'): 'Warum trägst du so etwas mit dir herum?\nBist du kein Samurai?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_16'): 'Ich bin in eine Kriegerfamilie hineingeboren,\ndoch mein Fokus liegt auf der Feldarbeit, nicht auf dem Schwert.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_17'): 'Ich habe diese Spelzen bei mir behalten,\nseit ich von zu Hause ging und mich zum Räuber erniedrigte.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_18'): 'Wäre Hirse nicht leichter zum Anfangen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_19'): 'Nein, Reis könnte genau das Richtige sein.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_2'): 'Was immer wir wollen? Wie zum...?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_20'): 'Meine Prinzessin hat Fähigkeiten geerbt,\nvon Takeribi, dem Kriegsgott,\nund Toyohana, der Erntegöttin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_21'): 'Daher werden ihre Kräfte stark von\nden fünf Körnern beeinflusst, und besonders vom Reis.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_22'): 'Wir pflanzen Reis. Sakuna wird stark. Ja?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_23'): 'In der Tat. Es wird leichter werden,\ndie Dämonen zurückzudrängen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_24'): 'Mit Reisanbau füllen wir unsere Bäuche\nund verringern die Dämonenzahl in einem Schlag.\nZwei Fliegen mit einer Klappe, wie man so sagt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_25'): 'Dann sei es so. Lady Sakuna geht jagen.\nWir bleiben hier und pflanzen den Reis.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_26'): 'Igitt... Wir müssen auch helfen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_27'): 'Keine Arbeit, kein Essen, vermute ich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_28'): 'Ich helfe auch mit!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_29'): 'Juhu!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_3'): 'Prinzessin, jetzt ist keine Zeit für einen königlichen\nNickerchen. Es mag hier eine Scheune geben, doch ihre\nVorräte sind aufgebraucht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_30'): 'Warte, ich hatte noch nichts dazu gesagt!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_31'): 'Tauemon, ich erwarte Großes von dir.\nGib auf den Feldern alles.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_32'): 'Dein Vertrauen wird nicht enttäuscht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_4'): 'Schläfst du deine Tage so weg wie in der\nHauptstadt, wirst du verhungern, bevor der Sommer kommt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_5'): 'Solange die Dämonen diese Insel beherrschen,\nist das Sammeln für die Menschenkinder allein zu große Last.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_6'): 'Deine Göttlichkeit gebietet, dass DU diejenige sein musst,\ndie handelt, meine Prinzessin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_7'): 'Du willst, dass ich hinausgehe und jage?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_8'): 'Deine Pflicht zu erfüllen heißt, deinen Standort\nhier Tag für Tag zu festigen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000203_9'): 'Üßerdem teilst du mit diesem Land eine tiefe Verbindung.\nKein besserer Ort, um deine Reise zu beginnen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000301_0'): 'Willkommen zurück, Göttin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000301_1'): 'Uuugh...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000301_2'): 'Hm? Ist etwas passiert?\nPersönlich bin ich erschöpft, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000301_3'): 'Geh zum alten Samurai.\nEr ist bei dem Schuppen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000301_4'): 'Ich habe ein schlechtes Gefühl dabei.\nUnd meine Intuition hat immer recht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_0'): 'Willst du uns verhungern lassen?!\nDu dummer Trottel!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_1'): 'Kinta, wütend zu sein ist schlecht.\nAlle machen Fehler.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_10'): 'Ich dachte, du sagtest, man könne dir vertrauen!\nWie willst du das wieder gutmachen?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_11'): 'Es schmerzt, es zu sagen, doch in Wahrheit\nmir fehlt nicht nur die Kampfesfertigkeit,\nsondern jegliches handwerkliche Geschick.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_12'): 'Ich liebe die Feldarbeit, und doch bin ich unfähig dazu.\nIch bin den Bauern nur im Weg gewesen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_13'): 'Ich ging davon aus, ich sei der Einzige hier, der etwas\nvom Reispflanzen versteht, und war also angeregt,\nesc zum ersten Mal richtig zu schaffen, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_14'): 'Oooh, ich habe mich selbst entehrt!\nZur Wiedergutmachung werde ich mir den Bauch aufschneiden,\nund...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_15'): 'D-Das ist völlig unnötig!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_16'): 'Stopp! Halt sofort!\nWenn du sterben willst, tu es irgendwo,\nwo wir nicht zusehen müssen, wie du ausblutest!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_17'): '*stöhnt*',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_18'): 'Niemand wünscht sich, dass du stirbst. Wir fragten\nnur, was wir ohne Essen tun sollen!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_19'): 'Ein Mund weniger zu füttern,\nschadet sicher auch nicht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_2'): 'Es tut mir sehr leid.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_20'): 'Er isst genug für fünf Leute.\nIch meine, wie gierig kann man sein?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_21'): 'Hört auf, mich zu ärgern!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_22'): 'Warum tut ihr Tauemon weh?!\nTauemon ist nett. Er hat nur einen Fehler gemacht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_23'): 'Ich bin kein Yanato-Mensch, aber ich verstehe.\nDas ist kein richtiger Weg zu handeln!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_24'): 'Okay, okay. Ich kann nicht streiten, nachdem ich\neinem Menschen von außerhalb des Landes zurechtgewiesen wurde.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_25'): 'Dein Name ist also Myrthe?\nUm deinetwillen schließen wir Frieden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_26'): 'Diesen Abend werden wir alle das Fleisch\nverspeisen, das ich gesammelt habe, und früh ins Bett gehen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_27'): 'Das gilt auch für dich, Stöpsel!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_28'): 'Hmph!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_29'): 'Oh!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_3'): 'Augh, ich bin so wütend!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_30'): 'Was ist diesmal los?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_31'): 'Ich bin gute Köchin!\nHeute mache ich Mahlzeit aus meinem Land!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_32'): 'Es wird soo köstlich sein!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_33'): 'I-Igitt. Ein Gericht aus deinem Land, sagst du?\nIch weiß nicht, woher du kommst, doch ich freue mich\ntrotzdem darauf.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_34'): 'Dann gebe ich dir dieses Fleisch.\nKoche uns etwas Leckeres.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_35'): 'Okay! Ich werde mich bemühen!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_4'): 'Du machst ganz schön Aufhebens.\nWas ist denn los?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_5'): 'Dieser Vollpfosten hat alle Samen ins Wasser verloren!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_6'): 'Waaas?! Bedeutet das, wir können keinen Reis anbauen?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_7'): 'Übrig bleibt nur diese kleine Handvoll.\nDer Rest ist...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_8'): 'Offenbar hat er nur BAUERN ZUGESCHAUT,\nund selbst nie einen Schwung Feldarbeit gemacht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000302_9'): 'Igitt, dieser Tropf ist eine Last!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_0'): 'Lady Sakuna, die übrig gebliebenen Samen sind gekeimt.\nEndlich ist es Zeit, sie zu pflanzen,\naber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_1'): 'Hast du diesmal die Sache im Griff?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_10'): 'Wie auch immer, wir können unser fortbestehendes\nLeben nicht den Menschenkindern anvertrauen.\nDie meisten sind doch nur Frauen und Kinder.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_11'): 'Mach dir keine Sorgen. Ich bin sicher, du wirst hervorragend sein.\nDu bist schließlich niemand anderes als die Nachfahrin\nvon Lady Toyohana.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_12'): 'Zumindest bin ich meines Wissens nach dem Ablauf sicher.\nIch bringe dir bei, wie es geht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_13'): 'Stell dich nicht so auf, nachdem du gestern das\ndort getan hast!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_2'): 'Ich lasse mich leicht mitreißen und\nzerquetsche am Ende die Setzlinge und zerstöre\ndie Feldwege.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_3'): 'Das klingt nach ziemlich viel Chaos.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_4'): 'Ich denke, das geht über bloßes "Unfähigkeit" hinaus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_5'): 'Hey, Tama, was schaust du da an?\nDu denkst doch nicht, dass du mich\nwieder zur Arbeit antreiben willst, oder?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_6'): 'Bedenk nur, wie lächerlich es wäre,\nwenn eine Erntegöttin den Reis pflanzt,\nden sie als Opfergabe erhält!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_7'): 'Nein, das ist überhaupt nicht seltsam.\nUnsere Erntegöttin ist außerordentlich\nrüstig.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_8'): 'Deine Mutter, Lady Toyohana, bebauerte jedes Jahr die Felder,\nwie auch die überragende Göttin,\nLady Kamuhitsuki.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:01000303_9'): 'Meinst du im Ernst? Selbst die edle Lady\nKamuhitsuki schaufelt im Reisfeld?\nDu machst wohl Witze!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_0'): 'Wir haben es bis zur Ernte geschafft,\naber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_1'): 'Die Halme wirken etwas kräftiger,\naber der Feldertrag ist bestenfalls knapp.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_2'): 'Ziehen wir die Samen für die nächste\nErnte ab, reicht es nicht zum Essen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_3'): 'Und doch, so karg er ist, der Ertrag\nhat tatsächlich zugenommen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_4'): 'Du hast Fortschritte gemacht, Prinzessin.\nDies ist die Periode, die deine\nGeduld auf die Probe stellt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:02000101_5'): 'Igitt. Wie verabscheuungswürdig.\nEin harter Winter wartet auf uns alle.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000201_0'): 'Sakuna, es ist schrecklich!\nKaimaru... Kaimaru ist...!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000201_1'): 'Fasse dich zusammen, Myrthe.\nWas ist mit Kaimaru passiert?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000201_2'): 'Er war heute Morgen hier, aber als ich mich\nkurz wegdrehte, war er weg.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000201_3'): 'Mister Tauemon ist losgegangen, um ihn zu suchen,\nist aber auch nicht zurückgekehrt. Was sollen wir tun?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000202_0'): 'Es ist nutzlos. Von hier sehen wir sie nicht.\nKommt sie zu weit, laufen sie Dämonen in die Arme.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000202_1'): 'Kannst du nicht irgendwas tun, Göttin?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000202_2'): 'Ich muss handeln, das ist klar.\nWenn ich nur wüsste, wo ich suchen soll...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000202_3'): 'Ich weiß! Nimm diesen Hund mit. Der Alte hat ihn\nhier gelassen, um ihm zu folgen, falls das passiert.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000202_4'): 'In Ordnung dann.\nIch werde versuchen, ihrer Spur zu folgen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_0'): 'Whoa, er ist huuuuge!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_1'): 'Sooo niedlich!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_10'): 'Kinder sind ziemlich aufmerksam.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_11'): 'Kwaaah! Kwakook.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_12'): 'Der Kappa sagt, wenn du seine Freunde rettest,\nwird er es dir vergelten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_13'): 'Hmmm...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_14'): '...Huh?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_15'): 'Warte... Du kannst das verstehen, Yui?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_16'): 'Oh...!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_17'): 'Nein, kann ich nicht. Mir kam nur so vor,\nals wollte es genau das sagen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_18'): 'Die Glaubwürdigkeit dieser Behauptung ist fraglich...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_19'): 'Was wirst du tun, Prinzessin?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_2'): 'Äh... Ich finde ihn irgendwie hässlich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_20'): 'Selbst wenn wir die Bitte des Kappa außen vor lassen,\nkönnte es in deinem Interesse sein, Kaimaru zu besänftigen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_21'): 'Richtig... Wir können nicht zulassen, dass er\nsich davonmacht, sobald wir weggucken.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_22'): 'Na gut dann. Ich gehe zum See.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_23'): 'Juhu!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_24'): 'Kwaaah!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_25'): 'Es ist tatsächlich zuletzt ziemlich laut hier...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_3'): 'Du bist mir also doch gefolgt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_4'): 'Sah-Sah! Aweee!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_5'): 'Er sagt, der Kappa hat Freunde. Sie wurden\nvon einem Dämon am See im Tal gefangen,\nund er will, dass du ihnen hilfst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_6'): 'Deshalb bist du allein losgezogen?\nWie oft habe ich dir gesagt, dass es\ngefährlich ist, von hier zu gehen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_7'): 'Sah-Sah... Ooooh...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_8'): 'Es gefällt dir nicht, wenn man dich um Dinge bittet,\ndaher wollte er dich nicht behelligen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000300_9'): 'Nrrrgh...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_0'): 'Alle Kappa sagen, sie werden es vergelten,\ngenau wie versprochen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_1'): 'Also war das mehr als bloße Pose.\nWie unerwartet gewissenhaft für ein Haufen\nnasser Seeigel.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_10'): 'Von nun an werden die Felder der Kappa\nzu Lady Sakunas Domäne gehören und so\nunseren Reisertrag steigern.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_11'): 'Mwahaha... Ich freue mich auf die kommende Ernte!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_2'): 'Aber was könnten sie wohl für uns tun, frage ich mich?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_3'): 'Nachdem wir unser Territorium über die umliegenden\nFelder, den östlichen Wald und das nördliche Tal\nausgedehnt haben...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_4'): '...könnten wir unsere Reisfelder\nmit der Hilfe der Kappa vergrößern.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_5'): 'Hmmm. Wäre es nicht leichtsinnig, ihnen\ndie Feldarbeit anzuvertrauen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_6'): 'Kwah! Kwawa!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_7'): 'Yah, yah!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_8'): 'Sie sagen, sie würden es gern tun.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:03000501_9'): 'Na gut, ich werde ihr Angebot nicht ablehnen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_0'): 'Ein Gespenst hat das gesagt, was?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_1'): 'Hast du eine Ahnung, was das bedeutet?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_10'): 'Gab es den?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_11'): 'Hm?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_12'): 'Ooooooh!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_13'): 'In der Tat. Den, den du von der Schwebenden Brücke\ndes Himmels geworfen hast: den Räuber Ishimaru.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_14'): 'Hmmm...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_15'): 'Falls das stimmt, könnte er vor uns hierher\ngekommen und den Ashigumo gejagt haben?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_16'): 'Selbst wenn nicht, der Gedanke, dass ein Mensch\nDämonen kontrolliert, ist...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_17'): 'Und doch ist es nicht unmöglich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_18'): 'Der Nebel, in den dieser Ishimaru geschleudert wurde,\nist neblig, mit weder Zeit noch Raum verbunden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_19'): 'Ganz einfach: Es ist das Fundament\nder beiden Reiche.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_2'): 'Die, die uns Ashigumo jagten,\nwaren zweifellos Dämonen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_20'): 'Die erste Kamuhitsuki erschaff also die Schwebende\nBrücke des Himmels, um diese formlose Zeit und\ndiesen Raum zu durchqueren?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_21'): 'Das ist korrekt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_22'): 'Und wenn dieser Nebel an keine Zeit und keinen Ort gebunden ist...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_23'): '...wo würde dann jemand landen, der hineingeschleudert wird?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_24'): 'Zum Beispiel auf dieser Insel, lange bevor\nihr alle ankamt... Meinst du das?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_25'): 'Ishimaru... ist auf dieser Insel?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_26'): 'Warte. Lass uns nicht vorgreifen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_27'): 'Was wir bisher wissen, ist, dass der Anführer\nder Dämonen MOGLICHERWEISE in der westlichen Festung ist.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_28'): 'Wir sollten zuerst dorthin, um es zu bestätigen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_29'): 'Ein berechtigter Punkt. Du bist stark genug geworden,\ndass ein Angriff auf die Festung kein Wahnsinn mehr ist.\nUnser Weg ist klar!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_3'): 'Und doch... die Dämonen, die uns nun plagen,\nsind organisierter, als sie sein sollten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_30'): 'Kontrolliere ich die Festung, wird diese ganze\nInsel endlich mein Gebiet sein!\nLady Kamuhitsuki sollte auch erfreut sein!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_31'): 'Hmph...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_32'): 'Oh... Ich meinte es nur im Scherz, Ashigumo.\nWir können alle miteinander auskommen, wirklich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_33'): 'Du magst stärker sein, doch du könntest\neine oder andere Lektion in Umsicht gebrauchen...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_4'): 'Es weckt Erinnerungen daran, wie wir waren,\nals wir neben Takeribi kämpften...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_5'): '...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_6'): 'Hmmm... Diese Brüder waren nie sehr gut\nin der Zusammenarbeit zwischen den Arten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_7'): 'Vielleicht steht jemand noch Mächtigeres\nals die regionalen Bosse über ihnen allen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_8'): 'Meinst du den Menschen,\nüber den das Gespenst sprach?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04000601_9'): 'Denk nach, Lady Sakuna...\nEs gab noch einen anderen Menschen außer uns,\nder im Erhabenen Reich aufgehalten wurde.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_0'): 'Du hattest eine lange, beschwerliche Reise.\nDanke, dass du uns von dem Reis erzählt hast.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_1'): 'Tama, ich kehre in die Hauptstadt zurück.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_10'): '...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_11'): 'Dieser wird dich führen.\nWenn du vorbereitet bist, sprich mit ihm.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_2'): 'Aber Prinzessin...\nWas ist mit Lady Kamuhitsukis Erlass?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_3'): 'Ich weiß sehr wohl, was ich tue.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_4'): 'Kokorowa ist meine einzige und alleinige Freundin.\nIch kann nicht ruhen, bevor ich sie\npersönlich befrage.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_5'): '...Ich verstehe, Prinzessin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_6'): 'Aber du darfst nicht zulassen, dass man\ndeine Anwesenheit entdeckt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_7'): 'Kannst du versprechen, dass du dich einschleichst,\ndeine Erledigungen erledigst und dann\ngerade hierher zurückkehrst?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_8'): 'Dann habe ich deinen Segen?! Ja, ich schwöre,\ndass ich sofort zurückkomme!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303_9'): 'Nun, da das erledigt ist...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303b_0'): 'Die Hauptstadt ist beträchtlich weit entfernt.\nIch muss vorbereitet aufbrechen, damit ich\nalles in einer Reise erledigen kann.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:04010303b_Choice'): 'In die Hauptstadt reisen?\n\nHinweis: In der Hauptstadt kannst du nicht speichern.\nEs wird empfohlen, vor dem Aufbruch zu speichern.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000101_0'): 'Hm?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000101_1'): 'Niemand ist draußen.\nSind sie alle im Haus?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_0'): 'Was regt dich so spät auf?\nBetrifft dich die Festung?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_1'): 'Ich habe zuletzt kaum schlafen können.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_10'): 'All unsere Räuberbrüder waren Ausgestoßene.\nEinige flohen ins Klosterleben. Andere fanden ihre\nHeimat von den Flammen des Krieges verwüstet.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_11'): 'Sie fanden mich, nach desertiert zu haben\nund ohne jeden Ort mehr zu gehen. Damals traf ich\nKaimars Vater und Ishimaru.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_12'): 'Na, das ist... unerwartet wortreich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_13'): 'Sie nahmen mich in ihre Gruppe auf, doch wie du\nweißt, kann ich kein Schwert führen. Was ist das\nfür ein Taschendieb, der seinem Namen nicht gerecht wird?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_14'): 'Ich dachte, ich könnte wenigstens die in den Bergen\nverborgenen Felder bearbeiten...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_15'): 'Ah. Ich kann mir denken, wie das ausging.\nDu kannst dir die Details sparen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_16'): '*hust* Wie auch immer, Ishimaru hegte Groll\ngegen mich, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_17'): 'Der Boss fand meine Unfähigkeit amüsant und\ngab mir den Spitznamen Tauemon.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_18'): 'Richtig. Ich glaube, ich verstehe das größere Bild.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_19'): 'Der Boss hat es wirklich gut verstanden,\nauf die Seinen aufzupassen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_2'): 'Wenn ich daran denke, dass Ishimaru der\nAnführer der Dämonen sein könnte, ich...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_20'): 'Aber eines Nachts... schlug Ishimaru den Boss nieder\nund übernahm die Führung der Gruppe für sich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_3'): 'Du denkst dir vermutlich zu viel daraus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_4'): 'Selbst so höre ich dir zu, wenn du\netwas zu sagen hast.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_5'): '*seufz*',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_6'): 'Ishimaru und ich gehörten zur selben\nRäuberbande.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_7'): 'Und unser Anführer war Kaimarus Vater.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_8'): 'Kaimaru ist der Sohn eines Räubers?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_9'): 'Er mag ein Räuber gewesen sein, doch er stahl nur\nvon gierigen Lords und ungerechten Kriegern.\nNur die Korrupten wurden Opfer seines Diebstahls.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_0'): 'Aber wie soll ich eine Insel erkunden,\nvon der ich nichts weiß?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_1'): 'Ah, perfekt. Ich werde ihn fragen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_2'): 'Ashigumo. Gibt es hier irgendwo\neinen Ort zum Jagen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_3'): 'Es gibt hier in der Nähe eine kleine Höhle. Die Dämonen\ndort sind schwach. Vielleicht findest du dort Nahrung.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_4'): 'Hmmm. Eine lange Reise klingt recht mühsam,\nalso folge ich deinem Vorschlag.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_5'): 'Ich pflege den Reis, bis er\nzu keimen beginnt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:102_FirstDungeon_Begin_6'): 'Glücklicherweise habe ich Werkzeug\nin der Scheune gefunden. Wir müssen Sakunas Mutter\ndankbar sein.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_0'): 'Endlich fertig. Es gab kaum Samen,\nund trotzdem zerreißt mir der Rücken.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_1'): 'Nein, du hast gut gearbeitet.\nKaum zu glauben, dass es dein erstes Mal ist.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_2'): 'Und kaum zu glauben, dass du irgendwelche\nErfahrung darin hast.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_3'): 'Was mache ich also jetzt?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_4'): 'Im Sommer beaufsichtigst du den Reis,\nwährend du auftauchendes Unkraut ziehst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_5'): 'Ich habe gehört, dass der richtige Wasserstand\nauch entscheidend für ihr Wachstum ist,\naber das können wir später machen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_6'): 'Zuerst müssen wir uns um das Unkraut kümmern.\nDas überlasse ich dir, bis Erntezeit ist.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_7'): '*seufz* Meine Buße bleibt unaufhaltsam...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_Message_0'): 'Du bist nun frei zu jagen\noder Reis zu pflanzen, wie du möchtest.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:103_TaueComplete_Message_1'): 'Prüfe deinen Handlungsverlauf unter "Aufträge"\nim Pausenmenü. Sieh nach,\nwenn du nicht weißt, wie es weitergeht.',
}

